export type BoardCategory =
  | "SBC"
  | "Microcontroller"
  | "AI Dev Kit"
  | "Development Board";

export type BoardInterface =
  | "GPIO"
  | "I2C"
  | "SPI"
  | "UART"
  | "ADC"
  | "DAC"
  | "PWM"
  | "CAN"
  | "USB"
  | "Wi-Fi"
  | "Bluetooth"
  | "Zigbee"
  | "Thread"
  | "CSI"
  | "PCIe"
  | "SWD"
  | "JTAG"
  | "Ethernet";

export type PinRole =
  | "power"
  | "ground"
  | "gpio"
  | "i2c"
  | "spi"
  | "uart"
  | "adc"
  | "dac"
  | "pwm"
  | "debug"
  | "system"
  | "special"
  | "reserved";

export type Pin = {
  position: number;
  label: string;
  role: PinRole;
  aliases?: string[];
  note?: string;
};

export type PinoutGroup = {
  label: string;
  pins: Pin[];
};

export type Pinout = {
  connector: string;
  layout: "dual-row" | "grouped";
  pins?: {
    left: Pin[];
    right: Pin[];
  };
  groups?: PinoutGroup[];
  notes: string[];
};

export type SourceLink = {
  label: string;
  url: string;
  type: "Docs" | "Pinout" | "Datasheet" | "Schematic" | "Manual";
};

export type Board = {
  id: string;
  name: string;
  vendor: string;
  category: BoardCategory;
  family: string;
  processor: string;
  logicLevel: string;
  power: string;
  formFactor: string;
  description: string;
  tags: string[];
  interfaces: BoardInterface[];
  highlights: string[];
  warnings: string[];
  sourceLinks: SourceLink[];
  pinout?: Pinout;
};

